def batch_key(value):
    if not isinstance(value, str):
        raise ValueError("invalid key")
    parts = [part.strip() for part in value.split(":")]
    if len(parts) != 3 or any(not part or any(c.isspace() for c in part) for part in parts):
        raise ValueError("invalid key")
    return parts[0].casefold(), parts[1].casefold(), parts[2]

def status_tally(events):
    seen = {}
    latest = {}
    for ticket, seq, status in events:
        if not isinstance(ticket, str) or not ticket or type(seq) is not int or seq < 1 or status not in ("open", "closed"):
            raise ValueError("invalid event")
        key = (ticket, seq)
        if key in seen and seen[key] != status:
            raise ValueError("conflicting event")
        seen[key] = status
        if ticket not in latest or seq > latest[ticket][0]:
            latest[ticket] = (seq, status)
    counts = {"open": 0, "closed": 0}
    for _, status in latest.values():
        counts[status] += 1
    return counts

def clip_spans(spans, low, high):
    if type(low) is not int or type(high) is not int or low > high:
        raise ValueError("invalid range")
    result = []
    for start, end in spans:
        if type(start) is not int or type(end) is not int or start > end:
            raise ValueError("invalid interval")
        a, b = max(start, low), min(end, high)
        if a < b:
            result.append((a, b))
    return result
